    } catch (const invalid_argument&) {
        return true;
    } catch (...) {
        return false;
    }
    return false;
}

int main() {
    assert((all_your_base::convert(16, {15, 15}, 2) ==
            vector<unsigned int>{1, 1, 1, 1, 1, 1, 1, 1}));
    assert((all_your_base::convert(2, {1, 1, 1, 1, 1, 1, 1, 1}, 16) ==
            vector<unsigned int>{15, 15}));
    assert((all_your_base::convert(10, {0, 0, 1, 2, 3}, 10) ==
            vector<unsigned int>{1, 2, 3}));
    assert(all_your_base::convert(10, {0, 0, 0}, 16).empty());
    assert((all_your_base::convert(97, {0, 0, 3, 46, 60}, 73) ==
            vector<unsigned int>{6, 10, 45}));

    assert(throws_invalid(1, {}, 10));
    assert(throws_invalid(0, {}, 10));
    assert(throws_invalid(10, {}, 1));
    assert(throws_invalid(10, {}, 0));
    assert(throws_invalid(2, {1, 0, 2}, 10));

    const unsigned int max_base = numeric_limits<unsigned int>::max();
    const vector<unsigned int> big{max_base - 1, 0, max_base - 2, 7};
    const vector<unsigned int> big_with_zeros{0, 0, max_base - 1, 0,
                                              max_base - 2, 7};
    const vector<unsigned int> normalized{max_base - 1, 0, max_base - 2, 7};

    const vector<unsigned int> binary =
        all_your_base::convert(max_base, big, 2);
    assert(all_your_base::convert(2, binary, max_base) == normalized);

    const vector<unsigned int> binary_with_zeros =
        all_your_base::convert(max_base, big_with_zeros, 2);
    assert(all_your_base::convert(2, binary_with_zeros, max_base) == normalized);

